// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

// Import the IncentivePricing interface
interface IIncentivePricing {
    enum IncentiveType {
        INTERVIEW_PARTICIPATION,
        FRIEND_REFERRAL,
        HEALTH_DATA_SHARING,
        TRIAL_PARTICIPATION,
        COMMUNITY_ENGAGEMENT
    }

    function calculateIncentivePrice(
        address community,
        IncentiveType incentiveType
    ) external view returns (uint256);
    function updateCommunityData(
        address community,
        uint256 newMemberCount,
        uint256 newInterviews,
        uint256 newReferrals,
        uint256 newFundsRaised
    ) external;
}

// Interface for Points Integration
interface IPointsIntegration {
    function convertAndAwardPoints(
        address community,
        address user,
        uint256 ethAmount
    ) external;
    function bulkConvertAndAwardPoints(
        address community,
        address[] calldata users,
        uint256[] calldata ethAmounts
    ) external;
}

contract CommunityReserve {
    address public owner;
    uint256 public totalReserve;

    // Fee percentages (in basis points: 10000 = 100%)
    uint256 public constant COMMUNITY_MEMBER_FEE = 4000; // 40%
    uint256 public constant LOCAL_DAO_RESERVE_FEE = 2500; // 25%
    uint256 public constant ONBOARDING_ORG_FEE = 1500; // 15%
    uint256 public constant TREASURY_FEE = 2000; // 20%

    // Contract references
    IIncentivePricing public incentivePricingContract;
    IPointsIntegration public pointsIntegrationContract;

    // Community data
    struct Community {
        address onboardingOrg;
        uint256 memberCount;
        uint256 totalInterviews;
        uint256 totalReferrals;
        uint256 totalDistributed;
        bool isRegistered;
        uint256 lastActivity;
    }

    // State mappings (matching senior's version for test compatibility)
    mapping(address => uint256) public userInvested;
    mapping(address => uint256) public communityRaised;
    mapping(address => bool) public registeredCommunities;
    mapping(address => address) public communityOnboardingOrg;

    // Enhanced mappings
    mapping(address => uint256) public userInvestments;
    mapping(address => uint256) public communityDistributed;
    mapping(address => Community) public communities;

    // Events - matching senior's FeeDistribution signature (7 parameters)
    event Invest(address indexed user, uint256 amount);
    event Distribute(address indexed community, uint256 amount);
    event CommunityRegistered(
        address indexed community,
        address indexed onboardingOrg
    );
    event DistributeWithFees(
        address indexed community,
        address indexed member,
        address indexed onboardingOrg,
        uint256 memberAmount,
        uint256 daoAmount,
        uint256 onboardingAmount,
        uint256 treasuryAmount
    );
    event IncentivePaid(
        address indexed community,
        address indexed recipient,
        uint256 amount,
        uint8 incentiveType
    );
    event IncentivePricingContractUpdated(address indexed newContract);
    event PointsIntegrationContractUpdated(address indexed newContract);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Invest in the community reserve
     */
    function invest() external payable {
        require(msg.value > 0, "Investment amount must be greater than 0");

        totalReserve += msg.value;
        userInvested[msg.sender] += msg.value;
        userInvestments[msg.sender] += msg.value;

        emit Invest(msg.sender, msg.value);
    }

    /**
     * @dev Register a new community
     */
    function registerCommunity(
        address community,
        address onboardingOrg
    ) external onlyOwner {
        require(community != address(0), "Invalid community address");
        require(onboardingOrg != address(0), "Invalid onboarding org address");
        require(
            !communities[community].isRegistered,
            "Community already registered"
        );

        communities[community] = Community({
            onboardingOrg: onboardingOrg,
            memberCount: 0,
            totalInterviews: 0,
            totalReferrals: 0,
            totalDistributed: 0,
            isRegistered: true,
            lastActivity: block.timestamp
        });

        registeredCommunities[community] = true;
        communityOnboardingOrg[community] = onboardingOrg;

        emit CommunityRegistered(community, onboardingOrg);
    }

    /**
     * @dev Update community statistics
     */
    function updateCommunityStats(
        address community,
        uint256 memberCount,
        uint256 interviews,
        uint256 referrals
    ) external onlyOwner {
        require(
            communities[community].isRegistered,
            "Community not registered"
        );

        Community storage comm = communities[community];
        comm.memberCount = memberCount;
        comm.totalInterviews = interviews;
        comm.totalReferrals = referrals;
        comm.lastActivity = block.timestamp;

        // Update incentive pricing contract
        if (address(incentivePricingContract) != address(0)) {
            incentivePricingContract.updateCommunityData(
                community,
                memberCount,
                interviews,
                referrals,
                communityRaised[community]
            );
        }
    }

    /**
     * @dev Pay incentive to community member with points integration
     */
    function payIncentive(
        address community,
        address recipient,
        IIncentivePricing.IncentiveType incentiveType
    ) external onlyOwner {
        require(
            communities[community].isRegistered,
            "Community not registered"
        );
        require(recipient != address(0), "Invalid recipient");

        uint256 incentiveAmount = getIncentivePrice(
            community,
            uint8(incentiveType)
        );
        require(
            address(this).balance >= incentiveAmount,
            "Insufficient contract balance"
        );

        // Pay the recipient
        payable(recipient).transfer(incentiveAmount);

        // Update community stats
        communities[community].totalDistributed += incentiveAmount;
        communityDistributed[community] += incentiveAmount;

        // Integrate with points system if available
        if (address(pointsIntegrationContract) != address(0)) {
            pointsIntegrationContract.convertAndAwardPoints(
                community,
                recipient,
                incentiveAmount
            );
        }

        emit IncentivePaid(
            community,
            recipient,
            incentiveAmount,
            uint8(incentiveType)
        );
    }

    /**
     * @dev Batch pay incentives to multiple recipients
     */
    function batchPayIncentives(
        address community,
        address[] calldata recipients,
        uint8[] calldata incentiveTypes
    ) external onlyOwner {
        require(
            recipients.length == incentiveTypes.length,
            "Arrays length mismatch"
        );
        require(
            communities[community].isRegistered,
            "Community not registered"
        );

        uint256 totalAmount = 0;
        uint256[] memory amounts = new uint256[](recipients.length);

        // Calculate total required amount
        for (uint256 i = 0; i < recipients.length; i++) {
            amounts[i] = getIncentivePrice(community, incentiveTypes[i]);
            totalAmount += amounts[i];
        }

        require(
            address(this).balance >= totalAmount,
            "Insufficient contract balance"
        );

        // Pay all recipients
        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "Invalid recipient");
            payable(recipients[i]).transfer(amounts[i]);
            emit IncentivePaid(
                community,
                recipients[i],
                amounts[i],
                incentiveTypes[i]
            );
        }

        // Update community stats
        communities[community].totalDistributed += totalAmount;
        communityDistributed[community] += totalAmount;

        // Integrate with points system if available
        if (address(pointsIntegrationContract) != address(0)) {
            pointsIntegrationContract.bulkConvertAndAwardPoints(
                community,
                recipients,
                amounts
            );
        }
    }

    /**
     * @dev Distribute funds to community with fee splitting
     */
    function distributeWithFees(
        address community,
        address member,
        uint256 amount
    ) external onlyOwner {
        require(
            communities[community].isRegistered,
            "Community not registered"
        );
        require(member != address(0), "Invalid member address");
        require(address(this).balance >= amount, "Insufficient balance");

        address onboardingOrg = communities[community].onboardingOrg;

        // Calculate fee distributions
        uint256 memberAmount = (amount * COMMUNITY_MEMBER_FEE) / 10000;
        uint256 daoAmount = (amount * LOCAL_DAO_RESERVE_FEE) / 10000;
        uint256 onboardingAmount = (amount * ONBOARDING_ORG_FEE) / 10000;
        uint256 treasuryAmount = (amount * TREASURY_FEE) / 10000;

        // Ensure we don't exceed the total amount due to rounding
        uint256 totalCalculated = memberAmount +
            daoAmount +
            onboardingAmount +
            treasuryAmount;
        if (totalCalculated > amount) {
            treasuryAmount =
                amount -
                (memberAmount + daoAmount + onboardingAmount);
        }

        // Distribute funds
        payable(member).transfer(memberAmount);

        // DAO gets its share (stays in contract for now)
        // payable(daoAddress).transfer(daoAmount); // TODO: Implement DAO address

        payable(onboardingOrg).transfer(onboardingAmount);

        // Treasury gets its share (stays in contract for now)
        // payable(treasuryAddress).transfer(treasuryAmount); // TODO: Implement treasury address

        // Update stats
        communities[community].totalDistributed += amount;
        communityDistributed[community] += amount;

        // Integrate with points system
        if (address(pointsIntegrationContract) != address(0)) {
            pointsIntegrationContract.convertAndAwardPoints(
                community,
                member,
                memberAmount
            );
        }

        emit DistributeWithFees(
            community,
            member,
            onboardingOrg,
            memberAmount,
            daoAmount,
            onboardingAmount,
            treasuryAmount
        );
    }

    /**
     * @dev Standard distribution without fee splitting
     */
    function distribute(address community, uint256 amount) external onlyOwner {
        require(
            communities[community].isRegistered,
            "Community not registered"
        );
        require(totalReserve >= amount, "Insufficient reserve balance");
        require(
            address(this).balance >= amount,
            "Insufficient contract balance"
        );

        totalReserve -= amount;
        communityRaised[community] += amount;
        communities[community].totalDistributed += amount;
        communityDistributed[community] += amount;

        // For now, keep funds in contract - in practice, this would transfer to community
        // payable(community).transfer(amount);

        emit Distribute(community, amount);
    }

    /**
     * @dev Set IncentivePricing contract
     */
    function setIncentivePricingContract(address _contract) external onlyOwner {
        incentivePricingContract = IIncentivePricing(_contract);
        emit IncentivePricingContractUpdated(_contract);
    }

    /**
     * @dev Set Points Integration contract
     */
    function setPointsIntegrationContract(
        address _contract
    ) external onlyOwner {
        pointsIntegrationContract = IPointsIntegration(_contract);
        emit PointsIntegrationContractUpdated(_contract);
    }

    /**
     * @dev Get incentive price for a community and type
     */
    function getIncentivePrice(
        address community,
        uint8 incentiveType
    ) public view returns (uint256) {
        if (address(incentivePricingContract) != address(0)) {
            return
                incentivePricingContract.calculateIncentivePrice(
                    community,
                    IIncentivePricing.IncentiveType(incentiveType)
                );
        }
        // Fallback pricing if no pricing contract
        return 0.01 ether; // Default 0.01 ETH
    }

    /**
     * @dev Get all incentive prices for a community
     */
    function getAllIncentivePrices(
        address community
    ) external view returns (uint256[5] memory prices) {
        for (uint256 i = 0; i < 5; i++) {
            prices[i] = getIncentivePrice(community, uint8(i));
        }
        return prices;
    }

    /**
     * @dev Get community information
     */
    function getCommunityInfo(
        address community
    )
        external
        view
        returns (
            address onboardingOrg,
            uint256 memberCount,
            uint256 totalInterviews,
            uint256 totalReferrals,
            uint256 totalDistributed,
            bool isRegistered,
            uint256 lastActivity
        )
    {
        Community memory comm = communities[community];
        return (
            comm.onboardingOrg,
            comm.memberCount,
            comm.totalInterviews,
            comm.totalReferrals,
            comm.totalDistributed,
            comm.isRegistered,
            comm.lastActivity
        );
    }

    /**
     * @dev Get contract balance
     */
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @dev Get registered communities (simplified - returns empty array)
     */
    function getRegisteredCommunities()
        external
        pure
        returns (address[] memory)
    {
        // Note: This is a simplified implementation
        // In practice, you'd want to maintain a dynamic array of registered communities
        address[] memory result = new address[](0);
        return result;
    }

    /**
     * @dev Get user investment amount
     */
    function getUserInvestment(address user) external view returns (uint256) {
        return userInvestments[user];
    }

    /**
     * @dev Get total amount raised by community
     */
    function getCommunityRaised(
        address community
    ) external view returns (uint256) {
        return communityRaised[community];
    }

    /**
     * @dev Emergency withdraw all funds (parameterless version for tests)
     */
    function emergencyWithdraw() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No funds to withdraw");
        totalReserve = 0;
        payable(owner).transfer(balance);
    }

    /**
     * @dev Emergency withdraw specific amount
     */
    function emergencyWithdraw(uint256 amount) external onlyOwner {
        require(
            amount <= address(this).balance,
            "Insufficient contract balance"
        );
        payable(owner).transfer(amount);
    }

    /**
     * @dev Transfer ownership
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "New owner cannot be zero address");
        owner = newOwner;
    }

    /**
     * @dev Get contract version for zkSync compatibility
     */
    function version() external pure returns (string memory) {
        return "2.0.0-zksync-points";
    }

    /**
     * @dev Check if contract is deployed on zkSync
     */
    function isZkSync() external view returns (bool) {
        // zkSync Era has specific system contracts at these addresses
        return
            address(0x8008).code.length > 0 || // SYSTEM_CONTEXT_CONTRACT
            address(0x8009).code.length > 0; // ETH_TOKEN_CONTRACT
    }

    /**
     * @dev Fallback function to receive ETH
     */
    receive() external payable {
        totalReserve += msg.value;
        userInvested[msg.sender] += msg.value;
        userInvestments[msg.sender] += msg.value;
        emit Invest(msg.sender, msg.value);
    }
}

contracts/IncentivePricing.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

contract IncentivePricing {
    address public owner;

    // Authorized contracts that can call updateCommunityData
    mapping(address => bool) public authorizedContracts;

    // Community Development Phases
    enum CommunityPhase {
        BOOTSTRAP, // 0: Starting phase (1-50 members)
        GROWTH, // 1: Growing phase (51-200 members)
        ESTABLISHED, // 2: Established phase (201-500 members)
        SCALED, // 3: Large scale (500+ members)
        PHARMA_READY // 4: Ready for pharmaceutical partnerships
    }

    // Incentive Types
    enum IncentiveType {
        INTERVIEW_PARTICIPATION,
        FRIEND_REFERRAL,
        HEALTH_DATA_SHARING,
        TRIAL_PARTICIPATION,
        COMMUNITY_ENGAGEMENT
    }

    // Community data structure
    struct CommunityData {
        uint256 memberCount;
        uint256 totalInterviews;
        uint256 totalReferrals;
        uint256 fundsRaised;
        CommunityPhase phase;
        bool isActive;
        uint256 lastUpdated;
    }

    // Base pricing for each incentive type (in wei)
    mapping(IncentiveType => uint256) public basePricing;

    // Phase multipliers (basis points: 10000 = 100%)
    mapping(CommunityPhase => uint256) public phaseMultipliers;

    // Registered communities
    address[] public registeredCommunities;
    mapping(address => CommunityData) public communities;

    // Events
    event CommunityRegistered(address indexed community, CommunityPhase phase);
    event CommunityUpdated(address indexed community, CommunityPhase newPhase);
    event ContractAuthorized(address indexed contractAddress);
    event ContractDeauthorized(address indexed contractAddress);
    event BasePriceUpdated(IncentiveType incentiveType, uint256 newPrice);
    event PhaseMultiplierUpdated(CommunityPhase phase, uint256 newMultiplier);

    // Modifiers
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    modifier onlyOwnerOrAuthorized() {
        require(
            msg.sender == owner || authorizedContracts[msg.sender],
            "Only owner can call this function"
        );
        _;
    }

    modifier validCommunity(address community) {
        require(
            communities[community].isActive,
            "Community not registered or inactive"
        );
        _;
    }

    constructor() {
        owner = msg.sender;
        _initializeBasePricing();
        _initializePhaseMultipliers();
    }

    /**
     * @dev Initialize base pricing for incentive types
     */
    function _initializeBasePricing() private {
        // Base prices in ETH converted to wei
        basePricing[IncentiveType.INTERVIEW_PARTICIPATION] = 0.01 ether;
        basePricing[IncentiveType.FRIEND_REFERRAL] = 0.005 ether;
        basePricing[IncentiveType.HEALTH_DATA_SHARING] = 0.008 ether;
        basePricing[IncentiveType.TRIAL_PARTICIPATION] = 0.02 ether;
        basePricing[IncentiveType.COMMUNITY_ENGAGEMENT] = 0.003 ether;
    }

    /**
     * @dev Initialize phase multipliers
     */
    function _initializePhaseMultipliers() private {
        // Multipliers as basis points (10000 = 100%)
        phaseMultipliers[CommunityPhase.BOOTSTRAP] = 15000; // 150% - Higher incentives for new communities
        phaseMultipliers[CommunityPhase.GROWTH] = 12000; // 120% - Good incentives for growing communities
        phaseMultipliers[CommunityPhase.ESTABLISHED] = 10000; // 100% - Standard rate
        phaseMultipliers[CommunityPhase.SCALED] = 8000; // 80%  - Lower incentives for large communities
        phaseMultipliers[CommunityPhase.PHARMA_READY] = 6000; // 60%  - Lowest incentives for mature communities
    }

    /**
     * @dev Authorize a contract to call restricted functions
     */
    function authorizeContract(address contractAddress) external onlyOwner {
        require(contractAddress != address(0), "Invalid contract address");
        authorizedContracts[contractAddress] = true;
        emit ContractAuthorized(contractAddress);
    }

    /**
     * @dev Deauthorize a contract
     */
    function deauthorizeContract(address contractAddress) external onlyOwner {
        authorizedContracts[contractAddress] = false;
        emit ContractDeauthorized(contractAddress);
    }

    /**
     * @dev Register a new community
     */
    function registerCommunity(
        address community,
        uint256 initialMemberCount
    ) external onlyOwner {
        require(community != address(0), "Invalid community address");
        require(
            !communities[community].isActive,
            "Community already registered"
        );

        CommunityPhase phase = determineCommunityPhase(
            initialMemberCount,
            0,
            0
        );

        communities[community] = CommunityData({
            memberCount: initialMemberCount,
            totalInterviews: 0,
            totalReferrals: 0,
            fundsRaised: 0,
            phase: phase,
            isActive: true,
            lastUpdated: block.timestamp
        });

        registeredCommunities.push(community);
        emit CommunityRegistered(community, phase);
    }

    /**
     * @dev Update community data and recalculate phase (callable by owner or authorized contracts)
     */
    function updateCommunityData(
        address community,
        uint256 newMemberCount,
        uint256 newInterviews,
        uint256 newReferrals,
        uint256 newFundsRaised
    ) external onlyOwnerOrAuthorized validCommunity(community) {
        CommunityData storage communityData = communities[community];

        // Update data
        communityData.memberCount = newMemberCount;
        communityData.totalInterviews = newInterviews;
        communityData.totalReferrals = newReferrals;
        communityData.fundsRaised = newFundsRaised;
        communityData.lastUpdated = block.timestamp;

        // Recalculate phase
        CommunityPhase newPhase = determineCommunityPhase(
            newMemberCount,
            newInterviews,
            newFundsRaised
        );

        if (newPhase != communityData.phase) {
            communityData.phase = newPhase;
            emit CommunityUpdated(community, newPhase);
        }
    }

    /**
     * @dev Calculate incentive price for a community and incentive type
     */
    function calculateIncentivePrice(
        address community,
        IncentiveType incentiveType
    ) external view validCommunity(community) returns (uint256) {
        CommunityData memory communityData = communities[community];

        uint256 basePrice = basePricing[incentiveType];
        uint256 multiplier = phaseMultipliers[communityData.phase];

        // Apply phase multiplier
        uint256 finalPrice = (basePrice * multiplier) / 10000;

        return finalPrice;
    }

    /**
     * @dev Determine community phase based on metrics
     */
    function determineCommunityPhase(
        uint256 memberCount,
        uint256 totalInterviews,
        uint256 fundsRaised
    ) public pure returns (CommunityPhase) {
        // Phase determination logic based on member count and activity

        // Pharma Ready: Large community with significant funding
        if (memberCount >= 1000 && fundsRaised >= 100 ether) {
            return CommunityPhase.PHARMA_READY;
        }

        // Scaled: Large community
        if (memberCount >= 500) {
            return CommunityPhase.SCALED;
        }

        // Established: Medium community with good activity
        if (
            memberCount >= 200 || (memberCount >= 100 && totalInterviews >= 50)
        ) {
            return CommunityPhase.ESTABLISHED;
        }

        // Growth: Growing community
        if (memberCount >= 50 || (memberCount >= 25 && totalInterviews >= 20)) {
            return CommunityPhase.GROWTH;
        }

        // Bootstrap: New/small community
        return CommunityPhase.BOOTSTRAP;
    }

    /**
     * @dev Get community data
     */
    function getCommunityData(
        address community
    )
        external
        view
        returns (
            uint256 memberCount,
            uint256 totalInterviews,
            uint256 totalReferrals,
            uint256 fundsRaised,
            CommunityPhase phase,
            bool isActive,
            uint256 lastUpdated
        )
    {
        CommunityData memory data = communities[community];
        return (
            data.memberCount,
            data.totalInterviews,
            data.totalReferrals,
            data.fundsRaised,
            data.phase,
            data.isActive,
            data.lastUpdated
        );
    }

    /**
     * @dev Get all registered communities
     */
    function getRegisteredCommunities()
        external
        view
        returns (address[] memory)
    {
        return registeredCommunities;
    }

    /**
     * @dev Get pricing for all incentive types for a community
     */
    function getAllIncentivePrices(
        address community
    )
        external
        view
        validCommunity(community)
        returns (uint256[5] memory prices)
    {
        for (uint i = 0; i < 5; i++) {
            prices[i] = this.calculateIncentivePrice(
                community,
                IncentiveType(i)
            );
        }
        return prices;
    }

    /**
     * @dev Update base pricing for an incentive type (owner only)
     */
    function updateBasePricing(
        IncentiveType incentiveType,
        uint256 newPrice
    ) external onlyOwner {
        require(newPrice > 0, "Price must be greater than 0");
        basePricing[incentiveType] = newPrice;
        emit BasePriceUpdated(incentiveType, newPrice);
    }

    /**
     * @dev Update phase multiplier (owner only)
     */
    function updatePhaseMultiplier(
        CommunityPhase phase,
        uint256 newMultiplier
    ) external onlyOwner {
        require(newMultiplier > 0, "Multiplier must be greater than 0");
        require(newMultiplier <= 50000, "Multiplier too high"); // Max 500%
        phaseMultipliers[phase] = newMultiplier;
        emit PhaseMultiplierUpdated(phase, newMultiplier);
    }

    /**
     * @dev Emergency function to deactivate a community
     */
    function deactivateCommunity(address community) external onlyOwner {
        communities[community].isActive = false;
    }

    /**
     * @dev Reactivate a community
     */
    function reactivateCommunity(address community) external onlyOwner {
        require(community != address(0), "Invalid community address");
        communities[community].isActive = true;
    }

    /**
     * @dev Transfer ownership
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "New owner cannot be zero address");
        owner = newOwner;
    }

    /**
     * @dev Get contract version for zkSync compatibility
     */
    function version() external pure returns (string memory) {
        return "1.0.0-zksync";
    }

    /**
     * @dev Check if contract is deployed on zkSync
     */
    function isZkSync() external view returns (bool) {
        // zkSync Era has specific system contracts at these addresses
        return
            address(0x8008).code.length > 0 || // SYSTEM_CONTEXT_CONTRACT
            address(0x8009).code.length > 0; // ETH_TOKEN_CONTRACT
    }

    /**
     * @dev Get phase name for frontend display
     */
    function getPhaseName(
        CommunityPhase phase
    ) external pure returns (string memory) {
        if (phase == CommunityPhase.BOOTSTRAP) return "Bootstrap";
        if (phase == CommunityPhase.GROWTH) return "Growth";
        if (phase == CommunityPhase.ESTABLISHED) return "Established";
        if (phase == CommunityPhase.SCALED) return "Scaled";
        if (phase == CommunityPhase.PHARMA_READY) return "Pharma Ready";
        return "Unknown";
    }

    /**
     * @dev Get incentive type name for frontend display
     */
    function getIncentiveTypeName(
        IncentiveType incentiveType
    ) external pure returns (string memory) {
        if (incentiveType == IncentiveType.INTERVIEW_PARTICIPATION)
            return "Interview Participation";
        if (incentiveType == IncentiveType.FRIEND_REFERRAL)
            return "Friend Referral";
        if (incentiveType == IncentiveType.HEALTH_DATA_SHARING)
            return "Health Data Sharing";
        if (incentiveType == IncentiveType.TRIAL_PARTICIPATION)
            return "Trial Participation";
        if (incentiveType == IncentiveType.COMMUNITY_ENGAGEMENT)
            return "Community Engagement";
        return "Unknown";
    }
}

